	    InventoryItem parentEntity = repository.findById(parentId).get();

		for (UUID childId : children) {
			SalesContract child = registry.project(SalesContract.class, childId);
			parentEntity.getSalesContracts().remove( child );
		}

	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
